from qiskit import QuantumCircuit
import math

def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # W state by successive zero-controlled Ry rotations
    # angle_i = 2*arcsin(1 / sqrt(n - i))
    for i in range(n):
        theta = 2.0 * math.asin(1.0 / math.sqrt(n - i))
        if i == 0:
            qc.ry(theta, i)
        else:
            controls = list(range(i))
            # all controls are required to be |0>
            # mcry with ctrl_state='0'*i avoids explicit X gates
            try:
                qc.mcry(theta, controls, i, ctrl_state='0' * i)
            except TypeError:
                # fallback for versions without ctrl_state
                for c in controls:
                    qc.x(c)
                qc.mcry(theta, controls, i)
                for c in controls:
                    qc.x(c)

    return qc
